#include "cubic_field.hpp"
E edet(std::vector<std::vector<E>>a){E d(1);for(int i=0;i<int(a.size());i++){int j=i;while(j<int(a.size())&&!a[j][i])j++;if(j==int(a.size()))return E();if(j!=i){std::swap(a[j],a[i]);d=-d;}E pivot=a[i][i];d=d*pivot;E iv=EF::inv(pivot);for(int j=i+1;j<int(a.size());j++){E v=a[j][i]*iv;for(int k=i;k<int(a.size());k++)a[j][k]=a[j][k]-v*a[i][k];}}return d;}
E sylvester(const EP&a,const EP&b,int da,int db){std::vector<std::vector<E>>M(da+db,std::vector<E>(da+db));for(int i=0;i<db;i++)for(int j=0;j<=da;j++)M[i][i+j]=a.coef(da-j);for(int i=0;i<da;i++)for(int j=0;j<=db;j++)M[db+i][i+j]=b.coef(db-j);return edet(M);}
E eresultant(EP a,EP b,int da,int db){if(a.deg()!=da||b.deg()!=db)return sylvester(a,b,da,db);E ans(1);while(!b.empty()){if(b.deg()==0)return ans*EF::pow(b[0],a.deg());int n=a.deg(),m=b.deg();EP r=erem(a,b);if(r.empty())return E();E c=EF::pow(b.back(),n-r.deg());if((n*m)%2)c=-c;ans=ans*c;a=std::move(b);b=std::move(r);}return E();}
#ifndef CUBIC_RESULTANT_FUNCTIONS_ONLY
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("usage: cubic_tests factor-index");EF::init(std::stoi(argv[1]));EF::check();std::mt19937 rng(635878);int n=0,drops=0;for(int da=1;da<=7;da++)for(int db=1;db<=7;db++)for(int mode=0;mode<4;mode++){EP a(da+1),b(db+1);for(auto&c:a)c=E(rng()%FF::N,rng()%FF::N,rng()%FF::N);for(auto&c:b)c=E(rng()%FF::N,rng()%FF::N,rng()%FF::N);if(mode&1)a.back()=E();if(mode&2)b.back()=E();a.trim();b.trim();if(mode)drops++;if(eresultant(a,b,da,db)!=sylvester(a,b,da,db))throw std::runtime_error("resultant comparison");n++;}std::cout<<"PASS: "<<n<<" extension fast-resultant/direct-Sylvester checks, "<<drops<<" coefficient drops; bounded implementation tests.\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
#endif
